async function checkSession(){try{const response=await fetch('/api/auth/me');const {user}=await response.json();if(!user){location.replace('/?auth=signin');return;}const label=document.getElementById('accountEmail');label.textContent=user.localOwner?'':user.email;label.hidden=Boolean(user.localOwner);document.getElementById('signOut').hidden=Boolean(user.localOwner);}catch{document.getElementById('accountEmail').textContent='Account unavailable';}}
document.getElementById('signOut').addEventListener('click',async()=>{const button=document.getElementById('signOut');button.disabled=true;try{const response=await fetch('/api/auth/signout',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(!response.ok)throw new Error();location.replace('/');}catch{button.textContent='Retry sign out';button.disabled=false;}});
window.addEventListener('pageshow',checkSession);
